import { addDays } from '../helpers/dates.js';
import { listOverdueLoans } from '../reports/overdue.js';
import { composeNotice } from './compose.js';

/** Loans due within this many days get a reminder in the morning run. */
const DUE_SOON_DAYS = 2;

/** Returns the reminders of the morning run for loans that fall due within two days of today. */
export function dueSoonNotices(store, today) {
  const until = addDays(today, DUE_SOON_DAYS);
  return store
    .listAllLoans()
    .filter((loan) => loan.returnedOn === null && loan.dueOn >= today && loan.dueOn <= until)
    .map((loan) => noticeFor(store, 'dueSoon', loan));
}

/** Returns the notices of the morning run for loans that are overdue today. */
export function overdueNotices(store, today) {
  return listOverdueLoans(store, today).map((loan) => noticeFor(store, 'overdue', loan));
}

function noticeFor(store, kind, loan) {
  const member = store.getMember(loan.memberId);
  const item = store.getItem(loan.itemId);
  return composeNotice(kind, { member, values: { title: item.title, dueOn: loan.dueOn } });
}
/** Returns the loans not returned whose due date is before `today`, the longest overdue first. */
export function listOverdueLoans(store, today) {
  return store
    .listAllLoans()
    .filter((loan) => loan.returnedOn === null && loan.dueOn < today)
    .sort((first, second) => first.dueOn.localeCompare(second.dueOn));
}
import { daysBetween } from '../helpers/dates.js';
import { DAILY_LATE_FEE_CENTS, GRACE_DAYS } from './schedule.js';

/** Returns the late fee in cents for a loan returned on `returnedOn`, 0 when none is due. */
export function assessLateFee({ loan, item, member, returnedOn }) {
  if (member.type === 'staff') return 0;
  const daysLate = daysBetween(loan.dueOn, returnedOn);
  if (daysLate <= GRACE_DAYS) return 0;
  return daysLate * DAILY_LATE_FEE_CENTS[item.format];
}
/** How long each format is lent for, in days, and how many times a loan of it may be renewed. */
export const LOAN_RULES = {
  book: { loanDays: 21, maxRenewals: 2 },
  dvd: { loanDays: 7, maxRenewals: 1 },
  magazine: { loanDays: 7, maxRenewals: 0 },
  laptop: { loanDays: 1, maxRenewals: 0 },
};

/** How many items a member of each type may have on loan at once. */
export const MAX_ITEMS_ON_LOAN = { adult: 30, junior: 10, staff: 50 };

/** How many years a new or renewed library card is valid, by member type. */
export const CARD_YEARS = { adult: 3, junior: 1, staff: 3 };

